etl.script:
CREATE TABLE CUSTOMER (
    ID INTEGER PRIMARY KEY,
    CUSTOMER_NAME VARCHAR(100),
    ACTIVE BOOLEAN,
    CREDIT DECIMAL(12, 2),
    NOTE VARCHAR(100)
);
INSERT INTO CUSTOMER VALUES (1, 'Ada "Ace"', TRUE, 12.50, NULL);
INSERT INTO CUSTOMER VALUES (2, 'Lin', FALSE, 7.25, 'follow up');

etl.query:
SELECT ID AS "customer_id", CUSTOMER_NAME AS "customer_name",
       ACTIVE AS "active", CREDIT AS "credit", NOTE AS "note"
FROM CUSTOMER ORDER BY ID

    {
        "id": ?{customer_id},
        "customer": {
            "name": ?{customer_name},
            "active": ?{active}
        },
        "credit": ?{credit},
        "note": ?{note},
        "source": "database"
    }
